contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 n, address actor) public {
        vm.assume(actor != address(0));
        uint256 amount = 1 wei;
        uint256 ok = 0;
        vm.deal(actor, uint256(n) * amount);
