pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 nDeposits, uint256 value, address depositor) public {
        // Keep the domain wide: any caller, any non-wrapping deposit count, any value.
        vm.assume(depositor != address(0));
        vm.assume(nDeposits < 4096);
        value = bound(value, 0, 1 ether);
        vm.deal(depositor, value * nDeposits + 1 ether);

        // Drive c through `receive` exactly nDeposits times.
        vm.startPrank(depositor);
        for (uint256 i = 0; i < nDeposits; i++) {
            (bool ok, ) = address(c).call{value: value}("");
            require(ok, "deposit rejected");
        }
        vm.stopPrank();

        // Universal rule: after every successful deposit the counter has grown by exactly one,
        // so it must equal the number of successful deposits; the unguarded increment in the
        // mutant breaks this correspondence once the counter can no longer be maintained.
        assertTrue(c.depositsCount() == nDeposits, "depositsCount must equal number of successful deposits");
    }
}

