pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor, uint256 priorDeposits) public {
        // 1. Keep the domain wide: any non-zero amount from any actor.
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        priorDeposits = bound(priorDeposits, 0, 4);

        // 2. Build up a few prior deposits so the counter is non-trivial,
        //    then drive the deciding deposit through receive.
        for (uint256 i = 0; i < priorDeposits; i++) {
            vm.deal(actor, amount);
            vm.prank(actor);
            (bool okPre, ) = address(c).call{value: amount}("");
            assertTrue(okPre);
        }

        uint256 countBefore = c.depositsCount();

        // 3. Deciding deposit through receive, observed via revert bool.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: whenever receive succeeds, the counter must have
        // strictly increased and must not have wrapped past its boundary.
        // Reference C guarantees this; the mutant (guard deleted) can succeed
        // at the overflow boundary and wrap, breaking the rule.
        assertTrue(!ok || (c.depositsCount() == countBefore + 1 && c.depositsCount() > countBefore));
    }
}

