pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep the domain wide: any actor, any amount up to the actor's dealable balance
        vm.assume(actor != address(0));
        vm.deal(actor, amount == 0 ? 1 : amount);

        // push depositsCount (storage slot 1) to the overflow boundary so the
        // explicit guard `depositsCount + 1 >= depositsCount` is the only thing
        // standing between a deposit and the wrap-around increment.
        address target = address(c);
        assembly {
            sstore(add(target, 1), not(0))
        }
        uint before_ = c.depositsCount();

        // drive c through receive() from the fuzzed actor with the fuzzed amount
        vm.prank(actor);
        (bool ok, ) = target.call{value: amount}("");

        // Rule: at the overflow boundary a deposit must be REJECTED by the guard,
        // so receive() reverts and depositsCount stays unchanged.
        // The mutant removed the guard, so the unguarded `depositsCount++` proceeds
        // (succeeds / corrupts the counter) and the rule is broken.
        assertTrue(!ok && c.depositsCount() == before_);
    }
}

