pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 nDeposits, uint256 amount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        nDeposits = bound(nDeposits, 1, 32);
        amount = bound(amount, 0, 1 ether);

        vm.deal(depositor, nDeposits * amount + 1 ether);

        bool allOk = true;
        for (uint256 i = 0; i < nDeposits; i++) {
            vm.prank(depositor);
            (bool ok, ) = address(c).call{value: amount}("");
            allOk = allOk && ok;
        }

        // General rule: every admissible deposit accepted via receive succeeds and
        // increments depositsCount by exactly one; after k accepted deposits the
        // counter must equal k (never wrapping / desynchronizing).
        assertTrue(allOk && c.depositsCount() == nDeposits);
    }
}

