pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        address owner = address(this);

        // owner deposits amount via receive()
        vm.deal(owner, amount * 2);
        (bool okDep,) = address(c).call{value: amount}(""");
        assertTrue(okDep);
        assertTrue(address(c).balance == amount);

        // owner withdraws all
        vm.prank(owner);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: any owner withdrawAll succeeds and fully empties the
        // contract, whatever the deposited amount was.
        assertTrue(ok && address(c).balance == 0);
    }
}

