pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Fund the contract directly with a positive amount (owner is this test
        // contract, which is msg.sender/deployer, so withdrawAll is authorized
        // and the transfer target accepts Ether).
        amount = bound(amount, 1, 1e30);
        vm.deal(address(c), amount);

        // No prank: call as deployer/owner. forge-std's Test contract has a
        // payable receive, so the reference's full-balance transfer succeeds.
        c.withdrawAll();

        // Universal rule: after withdrawAll, the contract holds no Ether.
        assertTrue(address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address attacker) public {
        require(attacker != c.owner());
        uint balBefore = address(c).balance;
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assert(!ok && address(c).balance == balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

